/* single loop: n iterations -> O(n) */
for (i = 0; i < n; i++) sum += a[i];

/* nested loops: n * n iterations -> O(n^2) */
for (i = 0; i < n; i++)
    for (j = 0; j < n; j++) count++;

/* halving loop: i = n, n/2, n/4, ... -> O(log n) */
for (i = n; i > 1; i = i / 2) count++;

/* linear outer, doubling inner -> O(n log n) */
for (i = 0; i < n; i++)
    for (j = 1; j < n; j = j * 2) count++;

#define MAX 100
int stack[MAX], top = -1;

void push(int x) {
    if (top == MAX - 1) return;      /* overflow */
    stack[++top] = x;
}
int pop(void) {
    if (top == -1) return -1;        /* underflow */
    return stack[top--];
}
int peek(void)    { return stack[top]; }
int isEmpty(void) { return top == -1; }

struct node { int data; struct node *next; };
struct node *top = NULL;

void push(int x) {
    struct node *p = malloc(sizeof(struct node));
    p->data = x; p->next = top; top = p;
}
int pop(void) {
    if (top == NULL) return -1;       /* underflow */
    struct node *p = top; int x = p->data;
    top = p->next; free(p);
    return x;
}

#define MAX 5
int q[MAX], front = -1, rear = -1;

void enqueue(int x) {
    if (rear == MAX - 1) return;          /* full */
    if (front == -1) front = 0;
    q[++rear] = x;
}
int dequeue(void) {
    if (front == -1 || front > rear) return -1;  /* empty */
    return q[front++];
}

int cq[N], front = -1, rear = -1;

void enqueue(int x) {
    if ((rear + 1) % N == front) return;   /* full */
    if (front == -1) front = 0;
    rear = (rear + 1) % N;
    cq[rear] = x;
}
int dequeue(void) {
    if (front == -1) return -1;            /* empty */
    int x = cq[front];
    if (front == rear) front = rear = -1;  /* last item */
    else front = (front + 1) % N;
    return x;
}

/* insert x at index pos in list[0..n-1] */
void insertAt(int list[], int *n, int pos, int x) {
    for (int i = *n; i > pos; i--)
        list[i] = list[i - 1];     /* shift right */
    list[pos] = x;
    (*n)++;
}
/* delete element at index pos */
void deleteAt(int list[], int *n, int pos) {
    for (int i = pos; i < *n - 1; i++)
        list[i] = list[i + 1];     /* shift left */
    (*n)--;
}

struct node { int data; struct node *next; };
struct node *head = NULL;

void insertBegin(int x) {                 /* O(1) */
    struct node *p = malloc(sizeof(struct node));
    p->data = x; p->next = head; head = p;
}
void insertEnd(int x) {                   /* O(n) */
    struct node *p = malloc(sizeof(struct node)), *t = head;
    p->data = x; p->next = NULL;
    if (head == NULL) { head = p; return; }
    while (t->next != NULL) t = t->next;
    t->next = p;
}

/* insert x after the pos-th node (1-based) */
void insertAfter(int pos, int x) {
    struct node *t = head;
    for (int i = 1; i < pos && t != NULL; i++) t = t->next;
    if (t == NULL) return;                /* invalid position */
    struct node *p = malloc(sizeof(struct node));
    p->data = x;
    p->next = t->next;                    /* link new node first */
    t->next = p;
}

void deleteBegin(void) {
    struct node *p = head;
    if (p) { head = p->next; free(p); }
}
void deleteKey(int key) {                 /* middle or any node */
    struct node *t = head, *prev = NULL;
    while (t && t->data != key) { prev = t; t = t->next; }
    if (t == NULL) return;                /* not found */
    if (prev) prev->next = t->next; else head = t->next;
    free(t);
}

void deleteEnd(void) {
    if (head == NULL) return;
    if (head->next == NULL) { free(head); head = NULL; return; }
    struct node *t = head;
    while (t->next->next != NULL) t = t->next;   /* second last */
    free(t->next);
    t->next = NULL;
}

struct node *reverse(struct node *head) {
    struct node *prev = NULL, *curr = head, *next;
    while (curr != NULL) {
        next = curr->next;
        curr->next = prev;
        prev = curr;
        curr = next;
    }
    return prev;                          /* new head */
}

struct dnode { int data; struct dnode *prev, *next; };

void insertAfterD(struct dnode *p, int x) {
    struct dnode *q = malloc(sizeof(struct dnode));
    q->data = x; q->prev = p; q->next = p->next;
    if (p->next) p->next->prev = q;
    p->next = q;
}
void deleteD(struct dnode **head, struct dnode *p) {
    if (p->prev) p->prev->next = p->next; else *head = p->next;
    if (p->next) p->next->prev = p->prev;
    free(p);
}

struct tnode { int key; struct tnode *left, *right; };

void preorder(struct tnode *r) {      /* Root Left Right */
    if (r) { visit(r); preorder(r->left); preorder(r->right); }
}
void inorder(struct tnode *r) {       /* Left Root Right */
    if (r) { inorder(r->left); visit(r); inorder(r->right); }
}
void postorder(struct tnode *r) {     /* Left Right Root */
    if (r) { postorder(r->left); postorder(r->right); visit(r); }
}

struct tnode *search(struct tnode *r, int key) {
    while (r && r->key != key)
        r = (key < r->key) ? r->left : r->right;
    return r;                                 /* NULL if absent */
}
struct tnode *insert(struct tnode *r, int key) {
    if (r == NULL) {
        r = malloc(sizeof(struct tnode));
        r->key = key; r->left = r->right = NULL;
    } else if (key < r->key) r->left = insert(r->left, key);
    else if (key > r->key) r->right = insert(r->right, key);
    return r;
}

struct avl { int key, height; struct avl *left, *right; };

struct avl *rightRotate(struct avl *y) {   /* fixes LL */
    struct avl *x = y->left;
    struct avl *T2 = x->right;
    x->right = y;                  /* y moves down to the right */
    y->left = T2;                  /* x's right subtree moves to y */
    y->height = 1 + max(ht(y->left), ht(y->right));
    x->height = 1 + max(ht(x->left), ht(x->right));
    return x;                      /* new subtree root */
}
